export default function Attendance() {
  const markAttendance = () => {
    fetch("http://localhost:5000/attendance", { method: "POST" })
      .then(() => alert("Attendance Marked"));
  };

  return (
    <div className="card">
      <h2>Face Based Attendance</h2>
      <button onClick={markAttendance}>
        Mark Attendance
      </button>
    </div>
  );
}
